INSERT INTO "public"."faq_items" ("id", "question", "answer", "group_name", "display_order", "is_active", "created_at", "updated_at") VALUES ('22222222-2222-2222-2222-000000000001', 'Apakah semua mobil bisa dengan driver?', 'Ya, semua unit di armada kami dapat disewa dengan driver profesional.', 'main', 1, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000002', 'Apakah bisa antar-jemput dari Stasiun KCIC Padalarang?', 'Ya, kami melayani charter dan transfer dari berbagai lokasi termasuk Stasiun KCIC Padalarang.', 'main', 2, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000003', 'Apakah harga paket sudah termasuk BBM?', 'Ya, paket All In Hiace sudah termasuk mobil, driver, BBM, tol, parkir, dan tiket penyeberangan.', 'main', 3, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000004', 'Apakah melayani perjalanan luar kota?', 'Ya, kami melayani perjalanan luar kota dalam maupun multi-hari. Lihat paket wisata untuk rute dan harga.', 'main', 4, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000005', 'Bagaimana cara reservasi?', 'Hubungi kami via WhatsApp dengan detail kebutuhan perjalananmu (tanggal, lokasi, jenis kendaraan). Tim kami akan membantu.', 'main', 5, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000006', 'Apakah ada biaya tambahan selain harga yang tertera?', 'Harga sudah fixed seperti tertera. Biaya tambahan (overtime, tujuan di luar coverage) akan dikonfirmasi sebelumnya.', 'main', 6, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000007', 'Bagaimana sistem pembayarannya?', 'Pembayaran bisa melalui transfer bank atau tunai. Untuk sewa dengan driver dan paket wisata, biasanya ada DP untuk mengunci jadwal dan pelunasan menjelang keberangkatan.', 'extra', 1, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000008', 'Bagaimana kalau perlu membatalkan reservasi?', 'Segera hubungi kami via WhatsApp. Pembatalan jauh sebelum tanggal keberangkatan tidak dikenakan biaya. Ketentuan DP akan dijelaskan tim kami saat konfirmasi.', 'extra', 2, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000009', 'Di area mana saja Mahessa melayani?', 'Kami berbasis di Cimahi, Bandung, dan Padalarang. Untuk tujuan luar kota seperti Jakarta, Yogyakarta, Bromo, hingga Bali, silakan lihat halaman paket perjalanan.', 'extra', 3, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000010', 'Bagaimana akomodasi driver untuk perjalanan multi-hari?', 'Untuk perjalanan multi-hari, akomodasi driver (penginapan dan makan) berada di luar harga paket dan menjadi tanggung jawab penyewa, atau bisa ditambahkan ke paket.', 'extra', 4, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000011', 'Bagaimana ketentuan overtime (kelebihan jam)?', 'Kelebihan durasi dihitung per jam dengan tarif yang telah disepakati sebelumnya. Kami sarankan konfirmasi rencana perjalanan agar durasi cukup.', 'extra', 5, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000012', 'Hiace muat berapa orang?', 'Toyota Hiace Premio kami nyaman untuk 14–16 penumpang termasuk bagasi. Cocok untuk rombongan keluarga, komunitas, hingga perjalanan dinas.', 'extra', 6, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00'), ('22222222-2222-2222-2222-000000000013', 'Bisa antar-jemput dari bandara atau stasiun?', 'Bisa. Kami rutin melayani transfer dari Stasiun KCIC Padalarang, Stasiun Bandung, serta Bandara Husein Sastranegara dan Kertajati. Cukup informasikan jadwal kedatanganmu.', 'extra', 7, true, '2026-09-01 04:59:39.29134+00', '2026-09-01 04:59:39.29134+00');